function validRecord(record) {
  return record && typeof record === 'object' && !Array.isArray(record) &&
    typeof record.id === 'string' && record.id.length > 0 &&
    typeof record.label === 'string' && typeof record.contact === 'string';
}

function applyDirectoryCommand(records, command) {
  if (!Array.isArray(records) || records.some(record => !validRecord(record))) throw new TypeError('invalid records');
  const ids = new Set();
  for (const record of records) {
    if (ids.has(record.id)) throw new RangeError('duplicate id');
    ids.add(record.id);
  }
  if (!command || typeof command !== 'object' || Array.isArray(command) || typeof command.type !== 'string') {
    throw new TypeError('invalid command');
  }

  if (command.type === 'LIST') return { records: records.map(record => ({ ...record })) };

  if (command.type === 'GET') {
    if (typeof command.id !== 'string') throw new TypeError('invalid id');
    const record = records.find(entry => entry.id === command.id);
    return { record: record ? { ...record } : null };
  }

  if (command.type === 'ADD') {
    if (!validRecord(command.record)) throw new TypeError('invalid record');
    if (ids.has(command.record.id)) throw new RangeError('duplicate id');
    return { records: records.concat(command.record).map(record => ({ ...record })) };
  }

  if (command.type === 'UPDATE') {
    if (typeof command.id !== 'string' || !command.changes || typeof command.changes !== 'object' || Array.isArray(command.changes)) {
      throw new TypeError('invalid update');
    }
    let found = false;
    const updated = records.map(record => {
      if (record.id !== command.id) return { ...record };
      found = true;
      return { ...record, ...command.changes };
    });
    return { records: updated, found };
  }

  if (command.type === 'REMOVE') {
    if (typeof command.id !== 'string') throw new TypeError('invalid id');
    const removed = records.find(record => record.id === command.id);
    return {
      records: records.filter(record => record.id !== command.id).map(record => ({ ...record })),
      removed: removed ? { ...removed } : null
    };
  }

  throw new TypeError('unknown command');
}

module.exports = { applyDirectoryCommand };

