'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['applyDirectoryCommand']);
const { applyDirectoryCommand } = api;

const records = [
  { id: 'a', label: 'Ada', contact: 'ada@example.com', group: 1 },
  { id: 'b', label: 'Ben', contact: 'ben@example.com' }
];
const snapshot = records.map(record => ({ ...record }));

const listed = applyDirectoryCommand(records, { type: 'LIST' });
assert.deepStrictEqual(listed.records, records);
assert.notStrictEqual(listed.records, records);
assert.notStrictEqual(listed.records[0], records[0]);
listed.records[0].label = 'changed';
assert.deepStrictEqual(records, snapshot);

const got = applyDirectoryCommand(records, { type: 'GET', id: 'b' });
assert.deepStrictEqual(got, { record: { id: 'b', label: 'Ben', contact: 'ben@example.com' } });
assert.notStrictEqual(got.record, records[1]);
assert.deepStrictEqual(applyDirectoryCommand(records, { type: 'GET', id: 'z' }), { record: null });

const newRecord = { id: 'c', label: 'Cy', contact: 'cy@example.com' };
const added = applyDirectoryCommand(records, { type: 'ADD', record: newRecord });
assert.deepStrictEqual(added.records, [...records, newRecord]);
for (let i = 0; i < added.records.length; i++) {
  assert.notStrictEqual(added.records[i], i < records.length ? records[i] : newRecord);
}
assert.throws(() => applyDirectoryCommand(records, { type: 'ADD', record: { id: 'a', label: 'Other', contact: 'x' } }), RangeError);

const changes = { id: 'forbidden', label: 'Ada Lovelace', extra: true };
const updated = applyDirectoryCommand(records, { type: 'UPDATE', id: 'a', changes });
assert.strictEqual(updated.found, true);
assert.deepStrictEqual(updated.records[0], {
  id: 'a', label: 'Ada Lovelace', contact: 'ada@example.com', group: 1, extra: true
});
assert.notStrictEqual(updated.records[0], records[0]);
assert.notStrictEqual(updated.records[1], records[1]);
assert.deepStrictEqual(changes, { id: 'forbidden', label: 'Ada Lovelace', extra: true });

const absent = applyDirectoryCommand(records, { type: 'UPDATE', id: 'z', changes: {} });
assert.strictEqual(absent.found, false);
assert.deepStrictEqual(absent.records, records);
assert.notStrictEqual(absent.records[0], records[0]);

const removed = applyDirectoryCommand(records, { type: 'REMOVE', id: 'a' });
assert.deepStrictEqual(removed, {
  records: [{ id: 'b', label: 'Ben', contact: 'ben@example.com' }],
  removed: { id: 'a', label: 'Ada', contact: 'ada@example.com', group: 1 }
});
assert.notStrictEqual(removed.records[0], records[1]);
assert.notStrictEqual(removed.removed, records[0]);
assert.deepStrictEqual(applyDirectoryCommand(records, { type: 'REMOVE', id: 'z' }), {
  records: records.map(record => ({ ...record })), removed: null
});
assert.deepStrictEqual(records, snapshot);

assert.throws(() => applyDirectoryCommand(null, { type: 'LIST' }), TypeError);
assert.throws(() => applyDirectoryCommand([null], { type: 'LIST' }), TypeError);
assert.throws(() => applyDirectoryCommand([{ id: '', label: 'A', contact: 'x' }], { type: 'LIST' }), TypeError);
assert.throws(() => applyDirectoryCommand([{ id: 'x', label: 1, contact: 'x' }], { type: 'LIST' }), TypeError);
assert.throws(() => applyDirectoryCommand([{ id: 'x', label: 'X', contact: 'x' }, { id: 'x', label: 'Y', contact: 'y' }], { type: 'LIST' }), RangeError);
assert.throws(() => applyDirectoryCommand(records, null), TypeError);
assert.throws(() => applyDirectoryCommand(records, { type: 'NOPE' }), TypeError);
assert.throws(() => applyDirectoryCommand(records, { type: 'GET', id: 1 }), TypeError);
assert.throws(() => applyDirectoryCommand(records, { type: 'ADD', record: [] }), TypeError);
assert.throws(() => applyDirectoryCommand(records, { type: 'UPDATE', id: 'a', changes: [] }), TypeError);
assert.throws(() => applyDirectoryCommand(records, { type: 'REMOVE', id: null }), TypeError);

